  _EntryCsvFile([String? content])
    : _file = XFile.fromData(
        Uint8List.fromList(
          utf8.encode(
            content ??
                'title,brand,pack,purchasePrice,sellingPrice,stock\n'
                    'Local rice,Store brand,1 kg,40,50,5\n',
          ),
        ),
        name: 'products.csv',
      );
  final XFile _file;
