    final snapshot = StoreStockSnapshot(
      storeId: 'store-review',
      storeName: 'Review Store',
      scope: 'All Store stock',
      generatedAt: DateTime.utc(2026, 9, 21, 10),
      products: products,
    );
    products.clear();
    expect(snapshot.rows, hasLength(2));
    final csv = (await tester.runAsync(
      () => snapshot.generate(StoreStockExportFormat.csv),
    ))!;
    final csvText = utf8.decode(csv);
    expect(csvText, contains("'=SUM(1,2)"));
    expect(csvText, contains('""oil""'));
    expect(csvText, isNot(contains('999')));
    final excel = (await tester.runAsync(
      () => snapshot.generate(StoreStockExportFormat.excel),
    ))!;
    final sheet = xls.Excel.decodeBytes(excel)['Current stock'];
    expect(
      sheet.cell(xls.CellIndex.indexByString('B7')).value,
      xls.TextCellValue('00123'),
    );
    expect(
      sheet.cell(xls.CellIndex.indexByString('C7')).value,
      xls.TextCellValue('001234567890'),
    );
    expect(
      sheet.cell(xls.CellIndex.indexByString('H7')).value,
      xls.IntCellValue(0),
    );
    expect(sheet.cell(xls.CellIndex.indexByString('H8')).value, isNull);
    expect(
      sheet.cell(xls.CellIndex.indexByString('K7')).value,
      xls.IntCellValue(264),
    );
    expect(
      sheet.cell(xls.CellIndex.indexByString('A7')).value,
      isA<xls.TextCellValue>(),
    );
    final pdf = (await tester.runAsync(
      () => snapshot.generate(StoreStockExportFormat.pdf),
    ))!;
    expect(ascii.decode(pdf.take(5).toList()), '%PDF-');
    const output = String.fromEnvironment('MOOL_STOCK_EXPORT_TEST_DIR');
    if (output.isNotEmpty) {
      await tester.runAsync(() async {
        await Directory(output).create(recursive: true);
        await File('$output/current-stock.csv').writeAsBytes(csv);
        await File('$output/current-stock.xlsx').writeAsBytes(excel);
        await File('$output/current-stock.pdf').writeAsBytes(pdf);
      });
    }
    expect(
      () => StoreStockSnapshot(
        storeId: '',
        storeName: 'Store',
        scope: 'All',
        generatedAt: DateTime.now(),
        products: [source],
      ),
      throwsFormatException,
    );
  });

  test(
    'D1 ledger reconciles physical stock without counting reservations twice',
    () {
      const line = StoreStockLedgerLine(
        productId: '00123',
        name: 'Oil',
        pack: '1 L',
        opening: 10,
        received: 5,
        issued: 3,
        closing: 12,
        reserved: 2,
        openingValueMinor: 10000,
        receivedValueMinor: 5000,
        issuedValueMinor: 3000,
        closingValueMinor: 12000,
      );
      expect(line.valid, isTrue);
      expect(line.available, 10);
      const bad = StoreStockLedgerLine(
        productId: 'bad',
        name: 'Oil',
        pack: '1 L',
        opening: 10,
        received: 5,
        issued: 3,
        closing: 10,
        reserved: 2,
      );
      expect(bad.valid, isFalse);
      const unknown = StoreStockLedgerLine(
        productId: 'unknown',
        name: 'Oil',
        pack: '1 L',
        opening: 10,
        received: 5,
        issued: 3,
        closing: 12,
        reserved: 2,
      );
      expect(unknown.valid, isTrue);
      expect(unknown.closingValueMinor, isNull);
      StoreStockLedgerSnapshot report(
        List<StoreStockLedgerLine> lines, {
        bool complete = true,
        String? method,
      }) => StoreStockLedgerSnapshot(
        accountId: 'account',
        storeId: 'store',
        storeName: 'Store',
        snapshotId: 'period-1',
        from: DateTime.utc(2026, 9, 1),
        until: DateTime.utc(2026, 10, 1),
        observedAt: DateTime.utc(2026, 10, 1),
        complete: complete,
        reviewOnly: true,
        lines: lines,
        valuationMethod: method,
      );
      expect(report([line], method: 'Weighted average').valid, isTrue);
      expect(report([line]).valid, isFalse);
      expect(report([unknown], complete: false).valid, isFalse);
      expect(report([unknown, unknown]).valid, isFalse);
      expect(report([unknown]).closingValueMinor, isNull);
      expect(report([]).closingValueMinor, isNull);
      expect(report([unknown]).disclosure, contains('not issued'));
    },
  );

