  testWidgets(
    'STOCK18 inline periods validate and never export current balances as history',
    (tester) async {
      var generated = 0, saved = 0;
      final scope = ChangeNotifier();
      var current = true;
      addTearDown(scope.dispose);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: StoreStockDownloadControls(
              storeId: 'store',
              storeName: 'Store',
              filteredProducts: [workspaceMasterCatalogue.first],
              filterDescription: '',
              isCurrent: () => current,
              scopeChanges: scope,
              generateFile: (snapshot, format) async {
                generated++;
                expect(snapshot.scope, 'All Store stock');
                return Uint8List.fromList([1]);
              },
              saveFile: (bytes, name, format) async {
                saved++;
                return true;
              },
            ),
          ),
        ),
      );
      Future<void> select(String period) async {
        await tester.tap(find.byKey(const Key('work-stock-period-selector')));
        await tester.pumpAndSettle();
        final chip = find.byKey(Key('work-stock-period-$period'));
        await tester.ensureVisible(chip);
        await tester.tap(chip);
        await tester.pumpAndSettle();
      }

      for (final period in ['today', 'week', 'month', 'custom']) {
        await select(period);
        for (final format in ['pdf', 'xlsx', 'csv']) {
          expect(
            tester
                .widget<TextButton>(
                  find.byKey(Key('work-stock-download-$format')),
                )
                .onPressed,
            isNull,
          );
        }
      }
      expect(find.byType(Dialog), findsNothing);
      expect(find.byType(BottomSheet), findsNothing);
      expect(find.text('Enter both dates as DD/MM/YYYY.'), findsOneWidget);
      Future<void> dates(String from, String to, String message) async {
        await tester.enterText(find.byKey(const Key('work-stock-from')), from);
        await tester.enterText(find.byKey(const Key('work-stock-to')), to);
        await tester.pumpAndSettle();
        expect(find.text(message), findsOneWidget);
      }

      await dates(
        '31/02/2024',
        '01/03/2024',
        'Enter valid dates as DD/MM/YYYY.',
      );
      await dates(
        '02/03/2024',
        '01/03/2024',
        'From date must be on or before To date.',
      );
      await dates('01/01/2999', '02/01/2999', 'Choose dates up to today.');
      await dates('29/02/2024', '01/03/2024', '29/02/2024 – 01/03/2024');
      expect(generated, 0);
      expect(saved, 0);
      FocusManager.instance.primaryFocus?.unfocus();
      await select('current');
      for (final format in ['pdf', 'xlsx', 'csv']) {
        await tester.tap(find.byKey(Key('work-stock-download-$format')));
        await tester.pumpAndSettle();
      }
      expect(generated, 3);
      expect(saved, 3);
      // Switching away and back must not revive an in-flight store scope.
      current = false;
      scope.notifyListeners();
      current = true;
      scope.notifyListeners();
      await tester.tap(find.byKey(const Key('work-stock-download-csv')));
      await tester.pumpAndSettle();
      expect(generated, 3);
      expect(saved, 3);
      expect(
        find.text('Your store changed. Reopen Reports & Downloads.'),
        findsOneWidget,
      );
      await tester.pumpWidget(const SizedBox.shrink());
      expect(tester.takeException(), isNull);
    },
  );

  testWidgets(
    'STOCK19 Android saver uses direct channel and reports failure without picker',
    (tester) async {
      const channel = MethodChannel('com.moolsocial.app/store_stock_download');
      final calls = <MethodCall>[];
      var failure = '';
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (call) async {
            calls.add(call);
            if (failure.isNotEmpty) throw PlatformException(code: failure);
            return true;
          });
      addTearDown(() {
        TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
            .setMockMethodCallHandler(channel, null);
      });
      final bytes = Uint8List.fromList([1, 2, 3]);
      for (final format in StoreStockExportFormat.values) {
        expect(
          await saveStoreStockFile(
            bytes,
            'stock-snapshot-20260921120000.${format.extension}',
            format,
          ),
          isTrue,
        );
        expect(calls.last.method, 'save');
        expect((calls.last.arguments as Map)['mimeType'], format.mimeType);
        expect((calls.last.arguments as Map)['bytes'], bytes);
      }
      failure = 'stock_download_failed';
      await expectLater(
        saveStoreStockFile(
          bytes,
          'stock-snapshot-20260921120000.csv',
          StoreStockExportFormat.csv,
        ),
        throwsA(
          isA<FormatException>().having(
            (e) => e.message,
            'message',
            contains('Could not save to Downloads'),
          ),
        ),
      );
      failure = 'stock_download_unsupported';
      await expectLater(
        saveStoreStockFile(
          bytes,
          'stock-snapshot-20260921120000.csv',
          StoreStockExportFormat.csv,
        ),
        throwsA(
          isA<FormatException>().having(
            (e) => e.message,
            'message',
            contains('Android 10'),
          ),
        ),
      );
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(
            channel,
            (_) async => throw MissingPluginException(),
          );
      await expectLater(
        saveStoreStockFile(
          bytes,
          'stock-snapshot-20260921120000.csv',
          StoreStockExportFormat.csv,
        ),
        throwsA(
          isA<FormatException>().having(
            (e) => e.message,
            'message',
            contains('unavailable'),
          ),
        ),
      );
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );

