      expect(save.hitTestable(), findsOneWidget);
      await captureStoreView(tester, 'counter-expanded-review-$caseId');
      final editItems = find.byKey(const Key('work-review-edit-items'));
      await tester.scrollUntilVisible(
        editItems,
        -300,
        scrollable: itemScroll,
        maxScrolls: 100,
      );
      await tester.pumpAndSettle();
      await tester.tap(editItems);
      await tester.pumpAndSettle();
      expect(work.workspaceOrderTotal, expectedTotal);
      await reveal(tester, review);
      await tester.tap(review);
      await tester.pumpAndSettle();
      expect(find.text('Review bill · $itemCount items'), findsOneWidget);
      expect(find.byKey(const Key('work-review-items-list')), findsOneWidget);
      expectFullTitleFits(reviewSummary, products.first.title);
      expect(work.workspaceOrderTotal, expectedTotal);
      if (scale > 1.3) {
        await tester.scrollUntilVisible(
          reviewTotal,
          300,
          scrollable: itemScroll,
          maxScrolls: 100,
        );
      } else {
        await tester.ensureVisible(reviewTotal);
      }
      await tester.pumpAndSettle();
      await captureStoreView(
        tester,
        'counter-compact-fifty-review-total-$caseId',
      );
      expect(find.text('Subtotal · $itemCount units'), findsOneWidget);
      final bankLabel = find.descendant(
        of: find.byKey(const Key('work-sale-payment-bank transfer')),
        matching: find.text('Bank Transfer'),
      );
      final bankParagraph = tester.renderObject<RenderParagraph>(bankLabel);
      for (final word in [
        const TextSelection(baseOffset: 0, extentOffset: 4),
        const TextSelection(baseOffset: 5, extentOffset: 13),
      ]) {
        expect(
          bankParagraph.getBoxesForSelection(word),
          hasLength(1),
          reason:
              'A payment-method word must not break inside the word at enlarged text.',
        );
      }
      final discount = find.byKey(const Key('work-counter-discount-value'));
      await reveal(tester, discount);
      await tester.enterText(discount, '10');
      final editable = find.descendant(
        of: discount,
        matching: find.byType(EditableText),
      );
      final inputState = tester.state<EditableTextState>(editable);
      tester.view.viewInsets = const FakeViewPadding(bottom: 240);
      await tester.pumpAndSettle();
      expect(tester.state<EditableTextState>(editable), same(inputState));
      expect(tester.widget<TextField>(discount).controller!.text, '10');
      expect(work.workspaceCounterPayableMinor, expectedTotal * 100);
      await tester.testTextInput.receiveAction(TextInputAction.done);
      await tester.pumpAndSettle();
      expect(work.workspaceCounterPayableMinor, expectedTotal * 90);
      await tester.enterText(discount, '100');
      await tester.pumpAndSettle();
      expect(tester.widget<FilledButton>(save).onPressed, isNull);
      await tester.enterText(discount, '10');
      await tester.testTextInput.receiveAction(TextInputAction.done);
      tester.view.viewInsets = FakeViewPadding.zero;
      await tester.pumpAndSettle();
      expect(tester.state<EditableTextState>(editable), same(inputState));
      expect(work.workspaceCounterPayableMinor, expectedTotal * 90);
      await captureStoreView(tester, 'counter-large-cart-discount-$caseId');
      expect(work.workspaceInvoices, isEmpty);
      expect(tester.takeException(), isNull);
    });
  }

  for (final scale in [1.0, 1.4]) {
    testWidgets(
      'COUNTER1919 public and private inventory search and scan $scale',
      (tester) async {
        final work = storeViewFixture(null, _ContactDraftFixtureStore());
        final publicProduct = workspaceMasterCatalogue.first.copyWith(
          stock: 24,
        );
        final privateProduct = workspaceMasterCatalogue
            .firstWhere((p) => p.id == 'salt-tata-1kg')
            .copyWith(stock: 24, publicListing: false);
        final emptyProduct = workspaceMasterCatalogue
            .firstWhere((p) => p.id == 'atta-aashirvaad-1kg')
            .copyWith(stock: 0);
        work.workspaceCatalogueItems
          ..clear()
          ..addAll([publicProduct, privateProduct, emptyProduct]);
        await mount(
          tester,
          route: '/app/work/workspace/dashboard',
          work: work,
          viewport: scale == 1 ? const Size(412, 915) : const Size(320, 568),
          textScale: scale,
        );
        await reveal(tester, find.byKey(const Key('work-quick-counter-sale')));
        await tester.tap(find.byKey(const Key('work-quick-counter-sale')));
        await tester.pumpAndSettle();
        await enterSaleCustomer(tester, '9829012345', name: 'Rakesh');
        final search = find.byKey(const Key('work-counter-product-search'));
        expect(tester.widget<TextField>(search).controller!.text, isEmpty);
        Future<void> revealSearch() async {
          for (
            var attempt = 0;
            attempt < 12 && search.evaluate().isEmpty;
            attempt++
          ) {
            final vertical = find.descendant(
              of: find.byKey(const Key('work-dashboard-counter-order-screen')),
              matching: find.byWidgetPredicate(
                (widget) =>
                    widget is Scrollable &&
                    widget.axisDirection == AxisDirection.down,
              ),
            );
            expect(vertical, findsOneWidget);
            await tester.drag(vertical, const Offset(0, 220));
            await tester.pumpAndSettle();
          }
          expect(search, findsOneWidget);
          await tester.ensureVisible(search);
          await tester.pumpAndSettle();
        }

        for (final product in [publicProduct, privateProduct, emptyProduct]) {
          await reveal(
            tester,
            find.byKey(Key('work-sale-product-${product.id}')),
          );
        }
        expect(
          tester
              .widget<IconButton>(
                find.byKey(Key('work-order-add-${emptyProduct.id}')),
              )
              .onPressed,
          isNull,
        );
        await revealSearch();
        await captureStoreView(
          tester,
          'counter-inventory-public-private-$scale',
        );
        await tester.enterText(search, 'Tata Salt');
        await tester.testTextInput.receiveAction(TextInputAction.search);
        await tester.pumpAndSettle();
        expect(
          find.byKey(Key('work-sale-product-${privateProduct.id}')),
          findsOneWidget,
        );
        expect(
          find.byKey(Key('work-sale-product-${publicProduct.id}')),
          findsNothing,
        );
        await reveal(
          tester,
          find.byKey(Key('work-order-add-${privateProduct.id}')),
        );
        await tester.tap(
          find.byKey(Key('work-sale-product-open-${privateProduct.id}')),
        );
        await tester.pumpAndSettle();
        expect(
          find.byKey(const Key('work-counter-store-product-page')),
          findsOneWidget,
        );
        expect(find.text('24 in stock'), findsOneWidget);
        await captureStoreView(tester, 'counter-private-product-$scale');
        await tester.tap(
          find.byKey(const Key('work-counter-product-add-confirm')),
        );
        await tester.pumpAndSettle();
        expect(work.workspaceOrderQuantities[privateProduct.id], 1);
        await revealSearch();
        await tester.tap(find.byKey(const Key('work-counter-usb-scan')));
        await tester.pumpAndSettle();
        Future<void> scan(String barcode) async {
          for (final character in barcode.split('')) {
            final key = LogicalKeyboardKey(character.codeUnitAt(0));
            await tester.sendKeyDownEvent(key, character: character);
            await tester.sendKeyUpEvent(key);
          }
          await tester.sendKeyEvent(LogicalKeyboardKey.enter);
          await tester.pumpAndSettle();
        }

        await scan(privateProduct.barcode);
        expect(work.workspaceOrderQuantities[privateProduct.id], 2);
        expect(
          find.byKey(const Key('work-counter-store-product-page')),
          findsNothing,
        );
        await captureStoreView(tester, 'counter-private-search-added-$scale');
        await scan(emptyProduct.barcode);
        expect(work.workspaceOrderQuantities[emptyProduct.id] ?? 0, 0);
        expect(
          find.text('This product is not available in your store inventory.'),
          findsOneWidget,
        );
        work.clearMessages();
        await tester.pumpAndSettle();
        await revealSearch();
        await tester.tap(find.byKey(const Key('work-counter-search-clear')));
        await tester.testTextInput.receiveAction(TextInputAction.search);
        await tester.pumpAndSettle();
        expect(tester.widget<TextField>(search).controller!.text, isEmpty);
        await reveal(
          tester,
          find.byKey(Key('work-sale-product-${publicProduct.id}')),
        );
        await reveal(
          tester,
          find.byKey(Key('work-sale-product-${privateProduct.id}')),
        );
        await reveal(tester, find.byKey(const Key('work-order-review')));
        await tester.tap(find.byKey(const Key('work-order-review')));
        await tester.pumpAndSettle();
        expect(find.text(privateProduct.title), findsOneWidget);
        final privateRow = find.byKey(
          ValueKey('work-review-item-${privateProduct.id}'),
        );
        expect(
          find.descendant(
            of: privateRow,
            matching: find.textContaining(privateProduct.pack),
          ),
          findsOneWidget,
        );
        expect(
          find.descendant(
            of: privateRow,
            matching: find.textContaining('2 × ₹56'),
          ),
          findsOneWidget,
        );
        expect(work.workspaceOrderTotal, 112);
        expect(
          work.workspaceCatalogueItems
              .firstWhere((p) => p.id == privateProduct.id)
              .publicListing,
          isFalse,
        );
        expect(
          work.workspaceCatalogueItems
              .where((p) => p.publicListing)
              .map((p) => p.id),
          [publicProduct.id, emptyProduct.id],
        );
        expect(
          work.workspaceCatalogueItems.where((p) => p.published),
          isEmpty,
          reason:
              'Visibility intent cannot publish an incomplete Store fixture.',
        );
        expect(work.workspaceInvoices, isEmpty);
        expect(tester.takeException(), isNull);
      },
    );
  }

  testWidgets('POSPOLISH quantity haptics confirm changes only', (
    tester,
  ) async {
    final work = storeViewFixture(null, _ContactDraftFixtureStore());
    final product = work.workspaceCatalogueItems.first;
    final index = work.workspaceCatalogueItems.indexOf(product);
    work.workspaceCatalogueItems[index] = product.copyWith(stock: 1);
    final haptics = <Object?>[];
    tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
      SystemChannels.platform,
      (call) async {
        if (call.method == 'HapticFeedback.vibrate') {
          haptics.add(call.arguments);
        }
        return null;
      },
    );
    addTearDown(
      () => tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
        SystemChannels.platform,
        null,
      ),
    );
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      viewport: const Size(360, 806),
    );
    await openCounterSaleFromSales(tester);
    await enterSaleCustomer(tester, '9000092501', name: 'POS feedback QA');
    haptics.clear();
    final add = find.byKey(Key('work-order-add-${product.id}'));
    final reduce = find.byKey(Key('work-order-reduce-${product.id}'));
    await reveal(tester, add);
    expect(tester.widget<IconButton>(reduce).onPressed, isNull);
    await tester.tap(add);
    await tester.pumpAndSettle();
    expect(work.workspaceOrderQuantities[product.id], 1);
    expect(haptics, ['HapticFeedbackType.selectionClick']);
    expect(tester.widget<IconButton>(add).onPressed, isNull);
    await tester.tap(add);
    await tester.pumpAndSettle();
    expect(haptics, hasLength(1));
    await tester.tap(reduce);
    await tester.pumpAndSettle();
    expect(work.workspaceOrderQuantities[product.id] ?? 0, 0);
    expect(haptics, [
      'HapticFeedbackType.selectionClick',
      'HapticFeedbackType.selectionClick',
    ]);
    expect(tester.widget<IconButton>(reduce).onPressed, isNull);
    expect(work.workspaceInvoices, isEmpty);
    expect(tester.takeException(), isNull);
  });

